// @ts-nocheck
'use client'

import { useRef, useState, Suspense, useEffect } from 'react'
import { Canvas, useFrame } from '@react-three/fiber'
import {
  OrbitControls,
  useGLTF,
  Environment,
  ContactShadows,
  Html,
  useProgress
} from '@react-three/drei'
import * as THREE from 'three'

function Loader() {
  const { progress } = useProgress()
  return (
    <Html center>
      <div className="text-zinc-400 font-mono">
        {progress.toFixed(0)}% loaded
      </div>
    </Html>
  )
}

function GR86Model({
  doorsOpen,
  carState,
}: {
  doorsOpen: boolean
  carState: 'off' | 'idle' | 'moving'
}) {
  const { scene } = useGLTF('/models/gr86.glb')
  const groupRef = useRef<THREE.Group>(null)
  const partsRef = useRef<{ [key: string]: THREE.Mesh }>({})
  const doorProgress = useRef(0)

  useEffect(() => {
    scene.traverse((child) => {
      if (child instanceof THREE.Mesh) {
        child.castShadow = true
        child.receiveShadow = true

        const name = child.name.toLowerCase()
        if (name.includes('door')) {
          partsRef.current[child.name] = child
        }
      }
    })
  }, [scene])

  useFrame((state, delta) => {
    const targetProgress = doorsOpen ? 1 : 0
    const speed = 3

    if (Math.abs(doorProgress.current - targetProgress) > 0.01) {
      doorProgress.current += (targetProgress - doorProgress.current) * speed * delta

      Object.values(partsRef.current).forEach((part) => {
        const name = part.name.toLowerCase()
        if (name.includes('fl')) {
          part.rotation.y = -doorProgress.current * 0.6
        } else if (name.includes('fr')) {
          part.rotation.y = doorProgress.current * 0.6
        }
      })
    }
  })

  useFrame((state) => {
    if (groupRef.current) {
      if (carState === 'idle') {
        groupRef.current.position.y = Math.sin(state.clock.elapsedTime * 15) * 0.003
      } else if (carState === 'moving') {
        groupRef.current.position.y = Math.sin(state.clock.elapsedTime * 2) * 0.01
      } else {
        groupRef.current.position.y = 0
      }
    }
  })

  return <primitive ref={groupRef} object={scene} scale={1.2} position={[0, -0.5, 0]} />
}

function Scene({ doorsOpen, carState }: { doorsOpen: boolean, carState: 'off' | 'idle' | 'moving' }) {
  return (
    <>
      <ambientLight intensity={0.5} />
      <spotLight
        position={[10, 10, 10]}
        angle={0.3}
        penumbra={1}
        intensity={1.5}
        castShadow
        shadow-mapSize={2048}
      />
      <pointLight position={[-10, -10, -10]} intensity={0.3} />

      <Suspense fallback={<Loader />}>
        <GR86Model doorsOpen={doorsOpen} carState={carState} />
        <ContactShadows
          position={[0, -0.5, 0]}
          opacity={0.6}
          scale={15}
          blur={2.5}
          far={4}
        />
        <Environment preset="city" />
      </Suspense>

      <OrbitControls
        enablePan={false}
        enableZoom={true}
        minPolarAngle={Math.PI / 8}
        maxPolarAngle={Math.PI / 2.2}
        minDistance={3}
        maxDistance={12}
        target={[0, 0, 0]}
      />
    </>
  )
}

export default function SetupPage() {
  const [carState, setCarState] = useState<'off' | 'idle' | 'moving'>('idle')
  const [doorsOpen, setDoorsOpen] = useState(false)

  return (
    <div className="min-h-screen bg-zinc-950">
      <div className="container mx-auto px-6 py-8">
        <h1 className="text-4xl font-bold text-zinc-100 mb-2">Setup</h1>
        <p className="text-zinc-400 mb-8">2022 Toyota GR86</p>

        <div className="flex flex-wrap gap-4 mb-8">
          <div className="flex gap-2">
            <button
              onClick={() => setCarState('off')}
              className={`px-4 py-2 rounded-lg text-sm font-medium transition-colors ${
                carState === 'off' ? 'bg-zinc-100 text-zinc-900' : 'bg-zinc-800 text-zinc-400 hover:bg-zinc-700'
              }`}
            >
              Engine Off
            </button>
            <button
              onClick={() => setCarState('idle')}
              className={`px-4 py-2 rounded-lg text-sm font-medium transition-colors ${
                carState === 'idle' ? 'bg-zinc-100 text-zinc-900' : 'bg-zinc-800 text-zinc-400 hover:bg-zinc-700'
              }`}
            >
              Idle
            </button>
            <button
              onClick={() => setCarState('moving')}
              className={`px-4 py-2 rounded-lg text-sm font-medium transition-colors ${
                carState === 'moving' ? 'bg-zinc-100 text-zinc-900' : 'bg-zinc-800 text-zinc-400 hover:bg-zinc-700'
              }`}
            >
              Moving
            </button>
          </div>

          <button
            onClick={() => setDoorsOpen(!doorsOpen)}
            className={`px-4 py-2 rounded-lg text-sm font-medium transition-colors ${
              doorsOpen ? 'bg-blue-600 text-white' : 'bg-zinc-800 text-zinc-400 hover:bg-zinc-700'
            }`}
          >
            {doorsOpen ? 'Close Doors' : 'Open Doors'}
          </button>
        </div>

        <div className="text-zinc-500 text-sm mb-4">
          Drag to rotate | Scroll to zoom
        </div>
      </div>

      <div className="h-[60vh] w-full">
        <Canvas
          camera={{ position: [5, 2.5, 5], fov: 45 }}
          shadows
          gl={{ antialias: true }}
        >
          <color attach="background" args={['#09090b']} />
          <Scene doorsOpen={doorsOpen} carState={carState} />
        </Canvas>
      </div>

      <div className="container mx-auto px-6 py-8">
        <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
          <div className="bg-zinc-900/50 rounded-lg p-4">
            <h3 className="text-zinc-100 font-medium mb-2">Engine States</h3>
            <p className="text-zinc-400 text-sm">
              {carState === 'off' && 'Engine is off - no vibration'}
              {carState === 'idle' && 'Engine running - subtle rumble vibration'}
              {carState === 'moving' && 'Engine revving - gentle bobbing motion'}
            </p>
          </div>
          <div className="bg-zinc-900/50 rounded-lg p-4">
            <h3 className="text-zinc-100 font-medium mb-2">Doors</h3>
            <p className="text-zinc-400 text-sm">
              Click "Open Doors" to swing both doors open
            </p>
          </div>
          <div className="bg-zinc-900/50 rounded-lg p-4">
            <h3 className="text-zinc-100 font-medium mb-2">Controls</h3>
            <p className="text-zinc-400 text-sm">
              Drag to rotate view | Scroll to zoom
            </p>
          </div>
        </div>
      </div>
    </div>
  )
}
